logger = logging.getLogger(__name__)

# GCU400 has 48 SPC per wave; a larger grid serializes in waves (see
# gcu400/ops/sum.py for the same fixed-grid + in-kernel stride precedent).
MAX_GRID = 48
# Per-program on-chip budget: x tile (fp32 after cast) + two fp32 accumulators.
DSM_BYTES = 448 * 1024


@libentry()
@triton.jit
def batch_norm_stats_kernel_flat(
    input_pointer,
    mean_pointer,
    invstd_pointer,
    batch_dim,
    channel_dim,
    spatial_dim: tl.constexpr,
    flat_dim,
    eps,
    count,
    input_batch_stride,
    BLOCK_B: tl.constexpr,
    BLOCK_F: tl.constexpr,
    CHANNELS_PER_TASK: tl.constexpr,
    NUM_STAGES: tl.constexpr,
    DEFERRED_TREES: tl.constexpr,
):
    """Column-block kernel over the contiguous (channel, spatial) flat dim.

    Each task reduces a BLOCK_F-wide contiguous column block of the
    row-major (batch, channel * spatial) view, i.e. memory-coalesced loads
    of BLOCK_F consecutive elements per batch row. Tasks are strided over
    the fixed 48-program grid, keeping the device in a single wave even
    for very large channel counts (the generic one-channel-per-program
    grid serializes in C / 48 waves).

    DEFERRED_TREES=1 keeps two [BLOCK_B, BLOCK_F] fp32 accumulators and
    reduces once in the epilogue (fewest per-element ops); 0 reduces each
    tile immediately (smaller accumulator footprint for fp32 tiles).
    """
    pid = tl.program_id(0)
    num_tasks = tl.cdiv(flat_dim, BLOCK_F)
    flat_offsets = tl.arange(0, BLOCK_F)
    for task in tl.range(pid, num_tasks, tl.num_programs(0)):
        flat_base = task * BLOCK_F
        flat_mask = flat_base + flat_offsets < flat_dim
        if DEFERRED_TREES == 1:
            sum_2d = tl.zeros([BLOCK_B, BLOCK_F], dtype=tl.float32)
            sumsq_2d = tl.zeros([BLOCK_B, BLOCK_F], dtype=tl.float32)
        else:
            sum_1d = tl.zeros([BLOCK_F], dtype=tl.float32)
            sumsq_1d = tl.zeros([BLOCK_F], dtype=tl.float32)
        for batch_start in tl.range(0, batch_dim, BLOCK_B, num_stages=NUM_STAGES):
            batch_offsets = batch_start + tl.arange(0, BLOCK_B)
            pointers = (
                input_pointer
                + batch_offsets[:, None] * input_batch_stride
                + (flat_base + flat_offsets)[None, :]
            )
            mask = (batch_offsets[:, None] < batch_dim) & flat_mask[None, :]
            x = tl.load(pointers, mask=mask, other=0.0).to(tl.float32)
            if DEFERRED_TREES == 1:
                sum_2d += x
                sumsq_2d += x * x
            else:
                sum_1d += tl.sum(x, axis=0)
                sumsq_1d += tl.sum(x * x, axis=0)
        if DEFERRED_TREES == 1:
            sum_1d = tl.sum(sum_2d, axis=0)
            sumsq_1d = tl.sum(sumsq_2d, axis=0)
        channel_sum = tl.sum(sum_1d.reshape(CHANNELS_PER_TASK, spatial_dim), axis=1)
        channel_sumsq = tl.sum(sumsq_1d.reshape(CHANNELS_PER_TASK, spatial_dim), axis=1)
        mean = channel_sum / count
        var = channel_sumsq / count - mean * mean
        invstd = 1.0 / tl.sqrt(var + eps)
        channel_base = flat_base // spatial_dim
        channel_offsets = channel_base + tl.arange(0, CHANNELS_PER_TASK)
        channel_mask = channel_offsets < channel_dim
        tl.store(mean_pointer + channel_offsets, mean, mask=channel_mask)
        tl.store(invstd_pointer + channel_offsets, invstd, mask=channel_mask)


@libentry()
@triton.jit
def batch_norm_stats_kernel_per_channel(
    input_pointer,
    mean_pointer,
    invstd_pointer,
    batch_dim,
    channel_dim,
    spatial_dim,
    eps,
    count,
    input_batch_stride,
    input_channel_stride,
    BLOCK_B: tl.constexpr,
    BLOCK_N: tl.constexpr,
    BATCH_STAGES: tl.constexpr,
    SPATIAL_STAGES: tl.constexpr,
    DEFERRED_TREES: tl.constexpr,
):
    """One channel per task, strided over the 48 SPCs of the grid.

    Every task walks the batch/spatial plane of a single channel with
    [BLOCK_B, BLOCK_N] tiles. Two accumulator shapes are kept because the
    winner depends on the tile size (probe: GCU400/L600, kernel-mode
    do_bench):

    - DEFERRED_TREES=1 keeps a [BLOCK_B, BLOCK_N] fp32 accumulator pair and
      folds it only once at the end. This is the fastest form for the wide
      16K-element tiles of the large shapes, but the accumulator dominates the
      on-chip budget.
    - DEFERRED_TREES=0 folds every tile into a [BLOCK_N] accumulator pair, so
      a narrow tile pays one cross-lane reduction per load instead. Cheaper
      for micro tiles, where the wide accumulator pair would cost more DSM
      than the data it saves.
    """
    pid = tl.program_id(0)
    spatial_offsets = tl.arange(0, BLOCK_N)
    for channel in tl.range(pid, channel_dim, tl.num_programs(0)):
        channel_base = input_pointer + channel * input_channel_stride
        if DEFERRED_TREES == 1:
            sum_2d = tl.zeros([BLOCK_B, BLOCK_N], dtype=tl.float32)
            sumsq_2d = tl.zeros([BLOCK_B, BLOCK_N], dtype=tl.float32)
        else:
            sum_1d = tl.zeros([BLOCK_N], dtype=tl.float32)
            sumsq_1d = tl.zeros([BLOCK_N], dtype=tl.float32)
        for batch_start in tl.range(0, batch_dim, BLOCK_B, num_stages=BATCH_STAGES):
            batch_offsets = batch_start + tl.arange(0, BLOCK_B)
            batch_mask = batch_offsets < batch_dim
            for spatial_start in tl.range(
                0, spatial_dim, BLOCK_N, num_stages=SPATIAL_STAGES
            ):
                spatial_vec = spatial_start + spatial_offsets
                pointers = (
                    channel_base
                    + batch_offsets[:, None] * input_batch_stride
                    + spatial_vec[None, :]
                )
                mask = batch_mask[:, None] & (spatial_vec < spatial_dim)[None, :]
                x = tl.load(pointers, mask=mask, other=0.0).to(tl.float32)
                if DEFERRED_TREES == 1:
                    sum_2d += x
                    sumsq_2d += x * x
                else:
                    sum_1d += tl.sum(x, axis=0)
                    sumsq_1d += tl.sum(x * x, axis=0)
        if DEFERRED_TREES == 1:
            sum_1d = tl.sum(sum_2d, axis=0)
            sumsq_1d = tl.sum(sumsq_2d, axis=0)
        total_sum = tl.sum(sum_1d)
        total_sumsq = tl.sum(sumsq_1d)
        mean = total_sum / count
        var = total_sumsq / count - mean * mean
        tl.store(mean_pointer + channel, mean)
        tl.store(invstd_pointer + channel, 1.0 / tl.sqrt(var + eps))


def _flat_launch_config(batch_dim, channel_dim, spatial_dim, flat_dim):
    """Probe-tuned (GCU400/L600, kernel-mode do_bench) launch geometry.

    - spatial == 1: target ~32 column tasks; deferred trees, num_warps 2.
    - Column blocks (spatial > 1): one 4096-wide block per task (wider blocks
      lose: 8192-wide is 1.46x slower on 64x512x512), a 32K-element tile
      budget, immediate per-tile trees and num_warps 4. Probes: 2048-wide
      blocks are 4.4x slower than 4096-wide on 64x512x512 (424us vs 97us), and
      the previous 16K budget cost 1.26x on 1024x1024x512 (2429us vs 1925us).
    """
    if spatial_dim == 1:
        block_f = max(32, triton.next_power_of_2(max(1, flat_dim // 32)))
        block_b = min(16384 // block_f, triton.next_power_of_2(batch_dim))
        return block_b, block_f, 2, 2, 1
    max_block_f = 4096
    block_f = max(
        spatial_dim,
        min(triton.next_power_of_2(max(1, flat_dim // MAX_GRID)), max_block_f),
    )
    if block_f >= 16384:
        # A single 16K-element block row per task: one [1, BLOCK_F] tile per
        # step needs the widest warp allocation (probe: nw4 -8.8%/-2.2%).
        return 1, block_f, 4, 1, 1
    budget = 32768
    block_b = min(max(1, budget // block_f), triton.next_power_of_2(batch_dim))
    return block_b, block_f, 4, 1, 0


def _per_channel_launch_config(batch_dim, channel_dim, spatial_dim):
    """Probe-tuned geometry for the one-channel-per-task kernel.

    Probes (GCU400/L600, kernel-mode do_bench) on 16x16x64, 16x16x1024,
    16x16x4098, 16x8x128x128 and 8x32x224x224:

    - 1024-wide tiles below a 8192-element spatial dim, 4096-wide above; the
      wider tile loses on the short-spatial shapes (28.5us vs 15.1us on
      16x16x4098).
    - A 32K-element tile budget keeps a single [BLOCK_B, BLOCK_N] tile close to
      the 448KB DSM budget (-28% on 8x32x224x224 vs the previous 16K budget).
    - num_warps 4 pays for itself as soon as the tile is wider than a micro
      tile, and SPATIAL_STAGES=2 hides the latency of the strided batch rows.
    - Micro tiles (<= 1024 elements) are launch-bound: narrow warps, no
      pipelining and immediate per-tile trees beat every deferred variant
      (-37% on 16x16x64). Below 64 elements the accumulator pair is free, so
      deferred trees win again (16x16x4098-style 16-element tiles).
    - Large tiles: deferred trees hold a third DSM buffer, so they only pay off
      while the grid is short of a full wave (channel_dim < MAX_GRID/2) and the
      spatial loop actually iterates. Probe table, deferred vs immediate:
        C=8 , 4 iters : 22.4us vs 25.8us (16x8x128x128, fp16)
        C=16, 5 iters : 13.3us vs 14.2us (16x16x4098, fp16)
        C=16, 49 iters: 71.8us vs 87.4us (4x16x448x448, fp16)
        C=32, 13 iters: 58.4us vs 43.0us (8x32x224x224, fp16)   <- immediate
        C=32, 16 iters: 125.7us vs 93.2us (16x32x256x256, fp16) <- immediate
        C=48, 4 iters : 224.6us vs 188.0us (64x64x128x128, fp16)<- immediate
        C=16, 1 iter  : 8.1us vs 7.0us (16x16x1024, fp16)       <- launch bound
    """
    block_n = min(
        triton.next_power_of_2(spatial_dim), 4096 if spatial_dim >= 8192 else 1024
    )
    tile_budget = 32768
    block_b = min(max(tile_budget // block_n, 1), triton.next_power_of_2(batch_dim))
    tile = block_b * block_n
    if tile < 64:
        return block_b, block_n, 1, 1, 1, 1
    if tile <= 1024:
        return block_b, block_n, 1, 1, 1, 0
    # Large tiles: keep the deferred accumulator pair only for grids that leave
    # at least half of the SPCs idle and whose spatial loop runs more than once.
    spatial_iters = triton.cdiv(spatial_dim, block_n)
    busy_tasks = min(MAX_GRID, channel_dim)
    deferred = 1 if spatial_iters > 1 and busy_tasks < MAX_GRID // 2 else 0
    return block_b, block_n, 4, 1, 2, deferred


def batch_norm_stats(input, eps):
    """Compute batch normalization statistics (mean and invstd) per channel.

    Args:
        input: Tensor of shape (N, C, *spatial_dims)
        eps: Small constant for numerical stability

    Returns:
        Tuple of (mean, invstd), each of shape (C,)
    """
    logger.debug("GEMS_ENFLAME BATCH_NORM_STATS")

    assert input.ndim >= 2, "Input must have at least 2 dimensions (N, C, ...)"

    # Reshape to 3D: (N, C, spatial)
    N = input.shape[0]
    C = input.shape[1]

    if input.ndim == 2:
        input_3d = input.unsqueeze(-1).contiguous()
    elif input.ndim >= 4:
        input_3d = input.flatten(2, -1).contiguous()
    else:
        input_3d = input.contiguous()

    spatial = input_3d.shape[2]
    flat_dim = C * spatial

    # Output tensors
    mean = torch.empty(C, dtype=torch.float32, device=input.device)
    invstd = torch.empty(C, dtype=torch.float32, device=input.device)
    # Element count per channel, precomputed on the host: a kernel-side
    # (batch_dim * spatial_dim).to(tl.float32) breaks when triton
    # specializes batch_dim == 1 into a python int.
    count = float(N * spatial)

    with torch_device_fn.device(input.device):
        # Two decompositions, picked by how many channel-aligned tasks the
        # shape can produce:
        #
        # - Column-block (flat) kernel: task boundaries land on channel
        #   boundaries, which needs a power-of-two spatial dim within the block
        #   cap and a batch dim > 1. It is the best form when it can keep the
        #   whole 48-SPC wave busy; below one full wave the per-channel arm
        #   (whose tasks stride over all channels) wastes less of the machine
        #   and wins (-37% on 16x16x64, -21% on 16x8x128x128).
        #   spatial == 1 keeps its dedicated column arm.
        # - Per-channel kernel: one channel per task, any spatial size.
        spatial_is_blockable = (
            (spatial & (spatial - 1)) == 0 and spatial <= 16384 and N > 1
        )
        flat_geometry = None
        flat_tasks = 0
        if spatial_is_blockable:
            flat_geometry = _flat_launch_config(N, C, spatial, flat_dim)
            flat_tasks = triton.cdiv(flat_dim, flat_geometry[1])
        use_flat_arm = spatial_is_blockable and (
            spatial == 1 or flat_tasks >= MAX_GRID
        )
        if use_flat_arm:
            block_b, block_f, num_warps, num_stages, deferred = flat_geometry
            channels_per_task = block_f // spatial
            # On-chip budget: fp32 x tile plus (deferred) fp32 accumulators.
            assert (
                block_b * block_f * 4 * (3 if deferred else 1) <= DSM_BYTES
            ), "flat kernel tile exceeds the DSM budget"
            grid = (min(MAX_GRID, flat_tasks),)
            batch_norm_stats_kernel_flat[grid](
                input_3d,
                mean,
                invstd,
                N,
                C,
                spatial,
                flat_dim,
                eps,
                count,
                input_3d.stride(0),
                BLOCK_B=block_b,
                BLOCK_F=block_f,
                CHANNELS_PER_TASK=channels_per_task,
                NUM_STAGES=num_stages,
                DEFERRED_TREES=deferred,
                num_warps=num_warps,
            )
        else:
            (
                block_b,
                block_n,
                num_warps,
                batch_stages,
                spatial_stages,
                deferred,
            ) = _per_channel_launch_config(N, C, spatial)
            assert (
                block_b * block_n * 4 * (3 if deferred else 1) <= DSM_BYTES
            ), "per-channel kernel tile exceeds the DSM budget"
            grid = (min(MAX_GRID, C),)
            batch_norm_stats_kernel_per_channel[grid](
                input_3d,
                mean,
                invstd,
                N,
                C,
                spatial,
                eps,
                count,
                input_3d.stride(0),
                input_3d.stride(1),
                BLOCK_B=block_b,
                BLOCK_N=block_n,
                BATCH_STAGES=batch_stages,
                SPATIAL_STAGES=spatial_stages,
                DEFERRED_TREES=deferred,
                num_warps=num_warps,
            )

    return mean, invstd


